mod leadership {
    use omnipaxos::{OmniPaxos, ClusterConfig, ServerConfig, storage::{Entry, NoSnapshot}, unicache::{UniCache, FieldCache, MaybeEncoded, lru_cache::LRUniCache}, messages::Message};
